  1→<!--
  2→  AC: @ui-task-board ac-3 — Task detail modal with full task info.
  3→  AC: @ui-task-board ac-6 — Action buttons: Start, Submit, Complete, Block, Add Note.
  4→-->
  5→<script lang="ts">
  6→	import type { TaskDetail } from '@kynetic-ai/shared';
  7→	import { base } from '$app/paths';
  8→	import {
  9→		fetchTask,
 10→		startTask,
 11→		submitTask,
 12→		completeTask,
 13→		blockTask,
 14→		addTaskNote
 15→	} from '$lib/api';
 16→	import { isStaticMode, ReadOnlyModeError } from '$lib/stores/mode.svelte';
 17→	import * as Dialog from '$lib/components/ui/dialog';
 18→	import { Badge } from '$lib/components/ui/badge';
 19→	import { Button } from '$lib/components/ui/button';
 20→	import { Textarea } from '$lib/components/ui/textarea';
 21→	import { Input } from '$lib/components/ui/input';
 22→	import { Separator } from '$lib/components/ui/separator';
 23→	import { getStatusClasses, formatAge } from './board-utils';
 24→
 25→	let {
 26→		open = $bindable(false),
 27→		taskRef = $bindable<string | null>(null),
 28→		onTaskUpdated
 29→	}: {
 30→		open?: boolean;
 31→		taskRef?: string | null;
 32→		onTaskUpdated?: () => void;
 33→	} = $props();
 34→
 35→	let task = $state<TaskDetail | null>(null);
 36→	let loading = $state(false);
 37→	let error = $state('');
 38→	let actionError = $state('');
 39→	let isSubmitting = $state(false);
 40→
 41→	// Note form
 42→	let noteContent = $state('');
 43→
 44→	// Block/Complete reason form
 45→	let reasonInput = $state('');
 46→	let showReasonFor = $state<'block' | 'complete' | null>(null);
 47→
 48→	$effect(() => {
 49→		if (open && taskRef) {
 50→			loadTask(taskRef);
 51→		} else if (!open) {
 52→			task = null;
 53→			error = '';
 54→			actionError = '';
 55→			noteContent = '';
 56→			reasonInput = '';
 57→			showReasonFor = null;
 58→		}
 59→	});
 60→
 61→	async function loadTask(ref: string) {
 62→		loading = true;
 63→		error = '';
 64→		try {
 65→			task = await fetchTask(ref);
 66→		} catch (err) {
 67→			error = err instanceof Error ? err.message : 'Failed to load task';
 68→		} finally {
 69→			loading = false;
 70→		}
 71→	}
 72→
 73→	async function reloadAndNotify() {
 74→		if (task) {
 75→			task = await fetchTask(task._ulid);
 76→		}
 77→		onTaskUpdated?.();
 78→	}
 79→
 80→	async function handleAction(action: () => Promise<void>) {
 81→		isSubmitting = true;
 82→		actionError = '';
 83→		try {
 84→			await action();
 85→			await reloadAndNotify();
 86→		} catch (err) {
 87→			if (err instanceof ReadOnlyModeError) {
 88→				actionError = err.message;
 89→			} else {
 90→				actionError = err instanceof Error ? err.message : 'Action failed';
 91→			}
 92→		} finally {
 93→			isSubmitting = false;
 94→		}
 95→	}
 96→
 97→	function handleStart() {
 98→		if (!task) return;
 99→		handleAction(() => startTask(task!._ulid));
100→	}
101→
102→	function handleSubmit() {
103→		if (!task) return;
104→		handleAction(() => submitTask(task!._ulid));
105→	}
106→
107→	function handleComplete() {
108→		if (!task || !reasonInput.trim()) return;
109→		const reason = reasonInput.trim();
110→		handleAction(async () => {
111→			await completeTask(task!._ulid, reason);
112→			reasonInput = '';
113→			showReasonFor = null;
114→		});
115→	}
116→
117→	function handleBlock() {
118→		if (!task || !reasonInput.trim()) return;
119→		const reason = reasonInput.trim();
120→		handleAction(async () => {
121→			await blockTask(task!._ulid, reason);
122→			reasonInput = '';
123→			showReasonFor = null;
124→		});
125→	}
126→
127→	function handleAddNote() {
128→		if (!task || !noteContent.trim()) return;
129→		const content = noteContent.trim();
130→		handleAction(async () => {
131→			await addTaskNote(task!._ulid, content);
132→			noteContent = '';
133→		});
134→	}
135→
136→	function formatDate(dateStr: string): string {
137→		return new Intl.DateTimeFormat('en-US', {
138→			month: 'short',
139→			day: 'numeric',
140→			hour: '2-digit',
141→			minute: '2-digit'
142→		}).format(new Date(dateStr));
143→	}
144→
145→	let statusInfo = $derived(task ? getStatusClasses(task.status) : null);
146→	let slug = $derived(task?.slugs?.[0] ?? task?._ulid?.slice(0, 8) ?? '');
147→</script>
148→
149→<Dialog.Root bind:open>
150→	<Dialog.Content class="max-w-2xl max-h-[85vh] overflow-y-auto" data-testid="task-detail-modal">
151→		{#if loading}
152→			<div class="flex items-center justify-center py-12">
153→				<p class="text-muted-foreground">Loading task...</p>
154→			</div>
155→		{:else if error}
156→			<div class="bg-destructive/10 text-destructive p-4 rounded-lg" role="alert">
157→				{error}
158→			</div>
159→		{:else if task && statusInfo}
160→			<Dialog.Header>
161→				<Dialog.Title data-testid="modal-task-title">{task.title}</Dialog.Title>
162→				<Dialog.Description>
163→					<span class="font-mono text-xs">@{slug}</span>
164→				</Dialog.Description>
165→			</Dialog.Header>
166→
167→			<div class="flex flex-col gap-4">
168→				<!-- Status, priority, type -->
169→				<div class="flex flex-wrap gap-2 items-center">
170→					<Badge class="{statusInfo.bg} {statusInfo.fg}" data-testid="modal-status-badge">
171→						{statusInfo.label}
172→					</Badge>
173→					<Badge variant="outline" data-testid="modal-priority">Priority {task.priority}</Badge>
174→					{#if task.type !== 'task'}
175→						<Badge variant="outline">{task.type}</Badge>
176→					{/if}
177→					{#if task.automation}
178→						<Badge variant="secondary" data-testid="modal-automation">
179→							{task.automation}
180→						</Badge>
181→					{/if}
182→				</div>
183→
184→				<!-- Spec ref -->
185→				{#if task.spec_ref}
186→					<div data-testid="modal-spec-ref">
187→						<p class="text-xs font-medium text-muted-foreground mb-0.5">Spec</p>
188→						<a
189→							href="{base}/specs?ref={encodeURIComponent(task.spec_ref)}"
190→							class="text-sm text-primary hover:underline font-mono"
191→						>
192→							{task.spec_ref}
193→						</a>
194→					</div>
195→				{/if}
196→
197→				<!-- Tags -->
198→				{#if task.tags?.length > 0}
199→					<div>
200→						<p class="text-xs font-medium text-muted-foreground mb-1">Tags</p>
201→						<div class="flex flex-wrap gap-1">
202→							{#each task.tags as tag}
203→								<Badge variant="secondary">{tag}</Badge>
204→							{/each}
205→						</div>
206→					</div>
207→				{/if}
208→
209→				<!-- Dependencies -->
210→				{#if task.depends_on?.length > 0}
211→					<div data-testid="modal-dependencies">
212→						<p class="text-xs font-medium text-muted-foreground mb-1">Dependencies</p>
213→						<ul class="text-sm space-y-0.5">
214→							{#each task.depends_on as dep}
215→								<li>
216→									<a
217→										href="{base}/tasks/board?ref={encodeURIComponent(dep)}"
218→										class="text-primary hover:underline font-mono text-xs"
219→									>
220→										{dep}
221→									</a>
222→								</li>
223→							{/each}
224→						</ul>
225→					</div>
226→				{/if}
227→
228→				<!-- Blocked by -->
229→				{#if task.blocked_by?.length > 0}
230→					<div data-testid="modal-blocked-by">
231→						<p class="text-xs font-medium text-destructive mb-1">Blocked By</p>
232→						<ul class="text-sm space-y-0.5">
233→							{#each task.blocked_by as blocker}
234→								<li class="text-muted-foreground font-mono text-xs">{blocker}</li>
235→							{/each}
236→						</ul>
237→					</div>
238→				{/if}
239→
240→				<!-- VCS refs -->
241→				{#if task.vcs_refs?.length > 0}
242→					<div data-testid="modal-vcs">
243→						<p class="text-xs font-medium text-muted-foreground mb-1">VCS</p>
244→						<ul class="text-sm space-y-0.5">
245→							{#each task.vcs_refs as ref}
246→								<li class="text-muted-foreground font-mono text-xs">{ref}</li>
247→							{/each}
248→						</ul>
249→					</div>
250→				{/if}
251→
252→				<!-- Plan ref (via derivation) -->
253→				{#if task.derivation}
254→					<div data-testid="modal-plan-ref">
255→						<p class="text-xs font-medium text-muted-foreground mb-0.5">Derivation</p>
256→						<p class="text-sm text-muted-foreground">{task.derivation}</p>
257→					</div>
258→				{/if}
259→
260→				<Separator />
261→
262→				<!-- AC: @ui-task-board ac-6 — Actions -->
263→				{#if !isStaticMode()}
264→					<div class="flex flex-wrap gap-2" data-testid="modal-actions">
265→						{#if task.status === 'pending'}
266→							<Button
267→								size="sm"
268→								onclick={handleStart}
269→								disabled={isSubmitting}
270→								data-testid="action-start"
271→							>
272→								{isSubmitting ? 'Starting...' : 'Start'}
273→							</Button>
274→						{/if}
275→
276→						{#if task.status === 'in_progress' || task.status === 'needs_work'}
277→							<Button
278→								size="sm"
279→								onclick={handleSubmit}
280→								disabled={isSubmitting}
281→								data-testid="action-submit"
282→							>
283→								{isSubmitting ? 'Submitting...' : 'Submit for Review'}
284→							</Button>
285→						{/if}
286→
287→						{#if task.status === 'in_progress' || task.status === 'pending_review'}
288→							<Button
289→								size="sm"
290→								variant="outline"
291→								onclick={() => {
292→									showReasonFor = 'complete';
293→									reasonInput = '';
294→								}}
295→								disabled={isSubmitting}
296→								data-testid="action-complete-toggle"
297→							>
298→								Complete
299→							</Button>
300→						{/if}
301→
302→						{#if task.status !== 'blocked' && task.status !== 'completed' && task.status !== 'cancelled'}
303→							<Button
304→								size="sm"
305→								variant="destructive"
306→								onclick={() => {
307→									showReasonFor = 'block';
308→									reasonInput = '';
309→								}}
310→								disabled={isSubmitting}
311→								data-testid="action-block-toggle"
312→							>
313→								Block
314→							</Button>
315→						{/if}
316→					</div>
317→
318→					<!-- Reason input for block/complete -->
319→					{#if showReasonFor}
320→						<div class="flex gap-2" data-testid="reason-input">
321→							<Input
322→								bind:value={reasonInput}
323→								placeholder="{showReasonFor === 'block' ? 'Block' : 'Completion'} reason..."
324→								class="flex-1"
325→							/>
326→							<Button
327→								size="sm"
328→								onclick={showReasonFor === 'block' ? handleBlock : handleComplete}
329→								disabled={isSubmitting || !reasonInput.trim()}
330→							>
331→								Confirm
332→							</Button>
333→							<Button
334→								size="sm"
335→								variant="ghost"
336→								onclick={() => {
337→									showReasonFor = null;
338→									reasonInput = '';
339→								}}
340→							>
341→								Cancel
342→							</Button>
343→						</div>
344→					{/if}
345→				{/if}
346→
347→				{#if actionError}
348→					<p class="text-sm text-destructive" data-testid="action-error">{actionError}</p>
349→				{/if}
350→
351→				<Separator />
352→
353→				<!-- Todos -->
354→				{#if task.todos && task.todos.length > 0}
355→					<div data-testid="modal-todos">
356→						<p class="text-xs font-medium text-muted-foreground mb-1">
357→							Todos ({task.todos.length})
358→						</p>
359→						<ul class="space-y-1">
360→							{#each task.todos as todo}
361→								<li class="flex items-start gap-2 text-sm">
362→									<span class="mt-0.5 text-xs">
363→										{#if todo.status === 'completed'}
364→											&#x2705;
365→										{:else if todo.status === 'in_progress'}
366→											&#x23F3;
367→										{:else}
368→											&#x23F8;&#xFE0F;
369→										{/if}
370→									</span>
371→									<span class:line-through={todo.status === 'completed'}>
372→										{todo.content}
373→									</span>
374→								</li>
375→							{/each}
376→						</ul>
377→					</div>
378→					<Separator />
379→				{/if}
380→
381→				<!-- Notes -->
382→				<div data-testid="modal-notes">
383→					<p class="text-xs font-medium text-muted-foreground mb-2">
384→						Notes ({task.notes?.length ?? 0})
385→					</p>
386→
387→					<!-- Add Note form -->
388→					{#if !isStaticMode()}
389→						<div class="mb-3 space-y-2" data-testid="modal-add-note">
390→							<Textarea
391→								placeholder="Add a note..."
392→								bind:value={noteContent}
393→								disabled={isSubmitting}
394→								rows={2}
395→							/>
396→							<Button
397→								size="sm"
398→								onclick={handleAddNote}
399→								disabled={isSubmitting || !noteContent.trim()}
400→								data-testid="action-add-note"
401→							>
402→								{isSubmitting ? 'Adding...' : 'Add Note'}
403→							</Button>
404→						</div>
405→					{/if}
406→
407→					<!-- Notes list -->
408→					<div class="space-y-3">
409→						{#each task.notes ?? [] as note}
410→							<div class="border rounded-md p-2.5" data-testid="note-item">
411→								<div class="flex justify-between items-start mb-1">
412→									<span class="text-[10px] text-muted-foreground">{note.author}</span>
413→									<span class="text-[10px] text-muted-foreground">{formatDate(note.created_at)}</span>
414→								</div>
415→								<p class="text-sm whitespace-pre-wrap">{note.content}</p>
416→							</div>
417→						{/each}
418→					</div>
419→				</div>
420→			</div>
421→		{/if}
422→	</Dialog.Content>
423→</Dialog.Root>
