   358→						</p>
   359→						<ul class="space-y-1">
   360→							{#each task.todos as todo}
   361→								<li class="flex items-start gap-2 text-sm">
   362→									<span class="mt-0.5 text-xs">
   363→										{#if todo.status === 'completed'}
   364→											&#x2705;
   365→										{:else if todo.status === 'in_progress'}
   366→											&#x23F3;
   367→										{:else}
   368→											&#x23F8;&#xFE0F;
   369→										{/if}
   370→									</span>
   371→									<span class:line-through={todo.status === 'completed'}>
   372→										{todo.content}
   373→									</span>
   374→								</li>
   375→							{/each}
   376→						</ul>
   377→					</div>
   378→					<Separator />
   379→				{/if}
   380→
   381→				<!-- Notes -->
