  9→<script lang="ts">
 10→	import { page } from '$app/stores';
 11→	import { onMount, onDestroy } from 'svelte';
 12→	import type { TaskSummary, BroadcastEvent } from '@kynetic-ai/shared';
 13→	import { fetchTasks, fetchAgentStatus, type AgentStatus } from '$lib/api';
 14→	import { subscribe, unsubscribe, on, off } from '$lib/stores/connection.svelte';
 15→	import { getProjectVersion } from '$lib/stores/project.svelte';
 16→	import { distributeToColumns, type BoardColumn } from '$lib/components/board/board-utils';
 17→	import BoardColumnComponent from '$lib/components/board/BoardColumn.svelte';
 18→	import ActiveFleetRow from '$lib/components/board/ActiveFleetRow.svelte';
 19→	import TaskDetailModal from '$lib/components/board/TaskDetailModal.svelte';
 20→	import BoardSkeleton from '$lib/components/board/BoardSkeleton.svelte';
 21→	import LayoutGrid from '@lucide/svelte/icons/layout-grid';
 22→	import List from '@lucide/svelte/icons/list';
 23→	import { Button } from '$lib/components/ui/button';
 24→	import { base } from '$app/paths';
 25→
 26→	let tasks = $state<TaskSummary[]>([]);
 27→	let columns = $state<BoardColumn[]>([]);
 28→	let loading = $state(true);
 29→	let error = $state('');
 30→	let agentStatus = $state<AgentStatus | null>(null);
 31→
 32→	// Detail modal state
 33→	let modalOpen = $state(false);
 34→	let selectedTaskRef = $state<string | null>(null);
 35→
 36→	// Track last processed URL ref to avoid infinite loops
 37→	let lastProcessedRef = $state('');
 38→
 39→	$effect(() => {
 40→		// Re-derive columns whenever tasks change
 41→		columns = distributeToColumns(tasks);
 42→	});
 43→
 44→	// AC: @ui-task-board ac-5 — Reload on project change
 45→	$effect(() => {
 46→		const version = getProjectVersion();
 47→		if (version > 0) {
 48→			loadBoard();
 49→		}
 50→	});
 51→
 52→	// Open task detail from URL param
 53→	$effect(() => {
 54→		const urlRef = $page.url.searchParams.get('ref');
 55→		if (urlRef && urlRef !== lastProcessedRef) {
 56→			lastProcessedRef = urlRef;
 57→			selectedTaskRef = urlRef;
 58→			modalOpen = true;
 59→		}
 60→	});
 61→
 62→	async function loadBoard() {
 63→		loading = true;
 64→		error = '';
 65→		try {
 66→			const [taskResponse, statusResponse] = await Promise.all([
 67→				fetchTasks({ limit: 500 }),
 68→				fetchAgentStatus().catch(() => null)
 69→			]);
 70→			tasks = taskResponse.items;
 71→			agentStatus = statusResponse;
 72→		} catch (err) {
 73→			error = err instanceof Error ? err.message : 'Failed to load board';
 74→		} finally {
 75→			loading = false;
 76→		}
 77→	}
 78→
 79→	function handleCardClick(task: TaskSummary) {
 80→		selectedTaskRef = task._ulid;
 81→		modalOpen = true;
 82→	}
 83→
 84→	function handleTaskUpdated() {
 85→		loadBoard();
 86→	}
 87→
 88→	// AC: @ui-task-board ac-5 — WebSocket real-time updates
 89→	function handleTaskUpdate(event: BroadcastEvent) {
 90→		loadBoard();
 91→	}
 92→
 93→	// AC: @ui-task-board ac-4 — Refresh agent status on agent events
 94→	function handleAgentUpdate(event: BroadcastEvent) {
 95→		fetchAgentStatus()
 96→			.then((status) => {
 97→				agentStatus = status;
 98→			})
 99→			.catch(() => {});
100→	}
101→
102→	// Polling for agent elapsed time updates
103→	let agentPollTimer: ReturnType<typeof setInterval> | undefined;
104→
105→	onMount(() => {
106→		loadBoard();
107→
108→		// AC: @ui-task-board ac-5 — Subscribe to task and agent updates
109→		subscribe(['tasks', 'agents']);
110→		on('tasks', handleTaskUpdate);
111→		on('agents', handleAgentUpdate);
112→
113→		// Poll agent status every 5s for elapsed time updates
114→		agentPollTimer = setInterval(() => {
115→			fetchAgentStatus()
116→				.then((status) => {
117→					agentStatus = status;
118→				})
119→				.catch(() => {});
120→		}, 5000);
121→	});
122→
123→	onDestroy(() => {
124→		off('tasks', handleTaskUpdate);
125→		off('agents', handleAgentUpdate);
126→		unsubscribe(['tasks', 'agents']);
127→		if (agentPollTimer) clearInterval(agentPollTimer);
128→	});
129→</script>
