143→			<Button
144→				variant="ghost"
145→				size="icon-sm"
146→				class="bg-accent"
147→				title="Board view"
148→				aria-pressed="true"
149→			>
150→				<LayoutGrid class="size-4" />
151→			</Button>
152→			<a href="{base}/tasks" title="List view">
153→				<Button variant="ghost" size="icon-sm" aria-pressed="false">
154→					<List class="size-4" />
155→				</Button>
156→			</a>
157→		</div>
158→	</div>
159→
160→	<!-- Error -->
