173→			<LayoutGrid class="size-12 text-muted-foreground/30 mb-4" />
174→			<h2 class="text-lg font-medium text-muted-foreground mb-1">No tasks yet</h2>
175→			<p class="text-sm text-muted-foreground">
176→				Create tasks using <code class="bg-muted px-1 rounded text-xs">kspec task add</code>
177→			</p>
178→		</div>
179→	{:else}
180→		<!-- AC: @ui-task-board ac-4 — Active Fleet Row -->
181→		<div class="px-6 pt-4">
182→			<ActiveFleetRow status={agentStatus} />
183→		</div>
184→
185→		<!-- AC: @ui-task-board ac-1 — Kanban Columns -->
186→		<div class="flex gap-4 overflow-x-auto p-6 pt-2 flex-1 min-h-0" data-testid="board-columns">
