		}
		return { label: `PR #${value}`, url: null };
	}

	// Direct URL
	if (ref.startsWith('http')) {
		// Extract meaningful label from GitHub-style URLs
		const prMatch = ref.match(/\/pull\/(\d+)/);
		if (prMatch) {
